function drawsAt(hz, cap, seconds = 10, jitter = 0) {
  const l = new FrameLimiter(cap);
  const gaps = [];
  let draws = 0, last = -1, seed = 7;
  const rnd = () => {
    seed = seed * 16807 % 2147483647;
    return seed / 2147483647 - 0.5;
  };
  for (let i = 0; i < hz * seconds; i++) {
    const t = 1e3 + i * 1e3 / hz + rnd() * 2 * jitter;
    if (l.shouldDraw(t)) {
      draws++;
      if (last >= 0) gaps.push(i - last);
      last = i;
    }
  }
  return { draws, gaps };
}
